/* The Studio on its own GitHub Pages address. Generated by scripts/build-studio-pages.mjs. No sign-in screen. */
(function(){
  'use strict';
  const BASE='/little-house-flower-studio/',VERSION='studio-20261015-7';
  const SW=new URL(BASE+'pages-sw.js',location.origin).href;
  window.LHF_PAGES_APP=true;
  window.LHF_PUBLIC_PREVIEW=true;
  window.LHF_SHARE_CONTEXT={customerURL:'/Little-House-Flower/',studioURL:BASE};
  document.documentElement.classList.remove('pages-locked');
  document.getElementById('pages-access')?.remove();
  const originalFetch=window.fetch.bind(window);
  const isControlled=()=>navigator.serviceWorker.controller?.scriptURL===SW;
  async function prepareWorker(){
    if(!('serviceWorker'in navigator)||!window.isSecureContext)throw new Error('Please open this website in Safari or Chrome.');
    const baseURL=new URL(BASE,location.origin).href;
    for(const registration of await navigator.serviceWorker.getRegistrations()){
      if(registration.scope===baseURL&&registration.active?.scriptURL!==SW)await registration.unregister();
    }
    const registration=await navigator.serviceWorker.register(SW,{scope:BASE,updateViaCache:'none'});
    if(isControlled())return;
    await new Promise((resolve,reject)=>{
      const cleanup=()=>{clearTimeout(timer);navigator.serviceWorker.removeEventListener('controllerchange',changed);};
      const changed=()=>{if(isControlled()){cleanup();resolve();}};
      const timer=setTimeout(()=>{cleanup();reject(new Error('Connection unavailable. Please refresh and try again.'));},20000);
      navigator.serviceWorker.addEventListener('controllerchange',changed);
      const claim=()=>{registration.active?.postMessage({type:'LHF_PAGES_CLAIM'});changed();};
      registration.installing?.addEventListener('statechange',claim);
      registration.waiting?.addEventListener('statechange',claim);
      claim();
    });
  }
  const ready=prepareWorker();
  // The original film and storefront render immediately; only API calls wait
  // until the project-scoped bridge can reach the permanent backend.
  ready.catch(()=>{});
  window.fetch=async function(input,init){
    const url=new URL(input instanceof Request?input.url:String(input),location.href);
    if(url.origin===location.origin&&url.pathname.startsWith(BASE+'api/'))await ready;
    return originalFetch(input,init);
  };
  function loadScript(path,type){return new Promise((resolve,reject)=>{
    const script=document.createElement('script');script.src=BASE+path+'?v='+VERSION;
    if(type)script.type=type;script.onload=resolve;script.onerror=()=>reject(new Error('The page could not load. Please refresh and try again.'));
    document.head.append(script);
  });}
  async function start(){
    try{
      // the opening film first, so it covers the Studio before the Studio draws; a failure to load it never stops the Studio
      await loadScript('shared/opening-film.js').then(()=>loadScript('opening.js')).catch(()=>{});
      await loadScript('app.mjs','module');
    }catch(error){
      const target=document.getElementById('app')||document.getElementById('main');
      if(!target)return;
      const message=document.createElement('p');message.setAttribute('role','alert');message.textContent='โหลดหน้าเว็บไม่สำเร็จ กรุณารีเฟรชแล้วลองอีกครั้ง · '+error.message;target.append(message);
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else void start();
})();
